const input = $input.first().json;

// AI Agent повертає результат у полі output
const rawText = input.output || input.text || input.response || '';

// Очищаємо від markdown якщо Claude додав
const clean = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  console.error('Observer parse error:', e.message);
  parsed = {
    signals:                     [],
    max_severity:                0,
    sentiment:                   'neutral',
    has_explicit_dropout_intent: false,
  };
}

// Беремо оригінальні дані з Observer Trigger
const trigger      = $('Observer Trigger').first().json;
const originalData = trigger.body || trigger;

// Валідація max_severity
const signals     = parsed.signals || [];
const maxSeverity = parsed.max_severity !== undefined
  ? parsed.max_severity
  : (signals.length > 0
      ? Math.max(...signals.map(s => s.severity || 0))
      : 0);

return [{
  json: {
    // Оригінальні дані студента з Planner
    student_id:        originalData.student_id,
    trigger:           originalData.trigger,
    student:           originalData.student,
    computed_signals:  originalData.computed_signals,
    homework_list:     originalData.homework_list,
    recent_messages:   originalData.recent_messages,
    raw_message_dates: originalData.raw_message_dates,

    // Результат Observer
    observer_result: {
      signals,
      max_severity:                maxSeverity,
      sentiment:                   parsed.sentiment                   || 'neutral',
      has_explicit_dropout_intent: parsed.has_explicit_dropout_intent || false,
    }
  }
}];

const input          = $input.first().json;
const observerResult = input.observer_result  || {};
const computed       = input.computed_signals || {};
let   signals        = [...(observerResult.signals || [])];

// Fix 1: null = "no activity at all as of date" -> treat as a huge gap,
// NOT 0 ("just active"). Upstream Compute All Signals sets these to null
// on purpose; every consumer must honour that.
const loginGapEff = computed.last_login_days_ago   == null ? 9999 : computed.last_login_days_ago;
const msgGapEff   = computed.last_message_days_ago == null ? 9999 : computed.last_message_days_ago;
const loggedInRecently =
  computed.last_login_days_ago != null && computed.last_login_days_ago <= 3;

// ── КРОК 1: Виправлення severity від Claude ──────────────────
signals = signals.map(s => {
  let sev = s.severity;

  switch (s.signal_type) {

    case 'late_homework':
      // §6.3 signal #1: chronic lateness is a primary dropout signal,
      // not noise — count it by recurrence, not only on a timing-shift.
      const lateN = computed.late_homework_count || 0;
      if      (computed.submission_timing_shift === true) sev = Math.max(sev, 6);
      else if (lateN >= 3) sev = Math.max(sev, 6);
      else if (lateN === 2) sev = Math.max(sev, 5);
      else                  sev = Math.min(sev, 4);
      break;

    case 'missed_homework':
      const missed = computed.missed_homework_count || 0;
      if      (missed >= 3) sev = Math.max(sev, 8);
      else if (missed === 2) sev = Math.max(sev, 7);
      else if (missed === 1) sev = Math.max(sev, 6);
      break;

    case 'login_gap':
      const loginDays = loginGapEff;
      if      (loginDays > 30) sev = Math.max(sev, 9);
      else if (loginDays > 21) sev = Math.max(sev, 8);
      else if (loginDays > 14) sev = Math.max(sev, 7);
      else if (loginDays > 7)  sev = Math.max(sev, 6);
      else                     sev = Math.min(sev, 3);
      break;

    case 'stopped_questions':
      const msgDays = msgGapEff;
      if (
        (computed.missed_homework_count || 0) === 0 &&
        loggedInRecently
      ) {
        sev = Math.min(sev, 3);
      } else if (msgDays >= 20) {
        sev = Math.max(sev, 7);
      }
      break;

    case 'negative_messages':
      if (observerResult.has_explicit_dropout_intent === true) {
        sev = Math.max(sev, 9);
      }
      break;

    case 'no_mentor_response':
      const ignoreDays = msgGapEff;
      if      (ignoreDays >= 7) sev = Math.max(sev, 9);
      else if (ignoreDays >= 3) sev = Math.max(sev, 7);
      break;
  }

  return { ...s, severity: sev };
});

// ── КРОК 2: Silent but OK ─────────────────────────────────────
// Fix 1: only a student with a real recent login (non-null) can be
// "silent but OK". Never-logged-in (null) must NOT get the cap.
const isSilentButOk =
  loggedInRecently                                  &&
  (computed.missed_homework_count || 0) === 0       &&
  (computed.late_homework_count   || 0) < 2         &&
  !observerResult.has_explicit_dropout_intent       &&
  computed.submission_timing_shift !== true;

if (isSilentButOk) {
  signals = signals.map(s => ({ ...s, severity: Math.min(s.severity, 4) }));
}

// ── КРОК 3: Перерахунок max_severity ─────────────────────────
let maxSeverity = signals.length > 0
  ? Math.max(...signals.map(s => s.severity || 0))
  : 0;

// ── КРОК 4: Модифікатори ──────────────────────────────────────
if (observerResult.has_explicit_dropout_intent === true) {
  maxSeverity = Math.max(maxSeverity, 8);
}
if (
  computed.submission_timing_shift === true &&
  signals.some(s => s.signal_type === 'late_homework')
) {
  maxSeverity = Math.max(maxSeverity, 5);
}

// ── КРОК 5: Червона зона (Fix 2: §6.3 — LMS OR chat, dropout
//    intent is an extra escalator, NOT a hard precondition) ────
const redZone =
  (computed.missed_homework_count || 0) >= 3 &&
  (loginGapEff >= 14 || msgGapEff >= 10);

if (redZone) maxSeverity = Math.max(maxSeverity, 9);
if (observerResult.has_explicit_dropout_intent === true &&
    (computed.missed_homework_count || 0) >= 1) {
  maxSeverity = Math.max(maxSeverity, 9);
}

// ── КРОК 6: Активні сигнали ───────────────────────────────────
const activeSignalsCount = signals.filter(s => s.severity >= 5).length;

// ── КРОК 7: Sentiment ─────────────────────────────────────────
let sentiment = observerResult.sentiment || 'neutral';
if      (maxSeverity >= 9) sentiment = 'critical';
else if (maxSeverity >= 7) sentiment = 'negative';
else if (maxSeverity >= 5) sentiment = 'neutral';
else                       sentiment = 'positive';

// ── ЛОГУВАННЯ ─────────────────────────────────────────────────
console.log('=== Calculate Severity Score ===');
console.log('student_id:', input.student_id);
console.log('loginGapEff:', loginGapEff, 'msgGapEff:', msgGapEff);
console.log('isSilentButOk:', isSilentButOk, 'redZone:', redZone);
console.log('final max_severity:', maxSeverity);
console.log('signals:', JSON.stringify(
  signals.map(s => s.signal_type + ':' + s.severity)
));

return [{
  json: {
    ...input,
    observer_result: {
      signals,
      max_severity:                maxSeverity,
      sentiment,
      has_explicit_dropout_intent: observerResult.has_explicit_dropout_intent || false,
      active_signals_count:        activeSignalsCount,
      red_zone:                    redZone,
      is_silent_but_ok:            isSilentButOk,
    }
  }
}];
